// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [3782988229, 3198818757, 3748979141, 3662897605, 418361797, 1223811525, 2919678405, 3661109701, 3498140101, 3388834245, 1684883909, 2771642821, 3475786181, 4163882206, 36127173, 4240110021];
const blocks = ["NFC U+010000-U+010FFF", "NFC U+011000-U+011FFF", "NFC U+012000-U+012FFF", "NFC U+013000-U+013FFF", "NFC U+014000-U+014FFF", "NFC U+015000-U+015FFF", "NFC U+016000-U+016FFF", "NFC U+017000-U+017FFF", "NFC U+018000-U+018FFF", "NFC U+019000-U+019FFF", "NFC U+01A000-U+01AFFF", "NFC U+01B000-U+01BFFF", "NFC U+01C000-U+01CFFF", "NFC U+01D000-U+01DFFF", "NFC U+01E000-U+01EFFF", "NFC U+01F000-U+01FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 65536 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
